import json

def load_config(path):
    with open(path, 'r') as f:
        config = json.load(f)
    missing = []
    if 'name' not in config:
        missing.append('name')
    if 'version' not in config:
        missing.append('version')
    if missing:
        raise ValueError(f"Missing required fields: {', '.join(missing)}")
    return config

